INSERT INTO "artifacts" VALUES('REQUIREMENT-e5758f09029a824837f05843','PRJ-457c6370f049cdb2538542dc','requirement',1,'accepted','{"acceptance":["AC-HISTORY"],"source_refs":["SRC-0d2b807ae30652c95ff26469"],"statement":"Historical program retains its accepted scope.","title":"Historical requirement"}','fb5bab710669257dfc829baac26a22679346d0c690c63fc820d24d2a1b9cfcd3','unassigned',1.78962432942663216e+09);
INSERT INTO "artifacts" VALUES('SCENARIO-c385b9e57ed45a03c6461495','PRJ-457c6370f049cdb2538542dc','scenario',1,'accepted','{"concurrent_journey":["Independent calls with distinct integer inputs may run concurrently because the function has no shared state or persistence."],"failure_journey":["If the result is not 5, the test fails and the delivery cannot be certified.","If the source or test cannot be read, stop and report the missing material instead of claiming success."],"nonfunctional":["The function is deterministic and performs no I/O or persistent mutation.","No latency or throughput target is supplied by the bounded source; performance acceptance is therefore not applicable."],"source_refs":["SRC-0d2b807ae30652c95ff26469"],"statement":"A caller supplies two integers to add(a, b), receives their exact sum, and the repository test confirms add(2, 3) == 5.","success_journey":["Invoke add(2, 3).","Observe the integer result 5.","Run the repository test and retain the passing result as the AC-CLOSED evidence."],"title":"Normal arithmetic scenario"}','c25da034b44fdcc608e55e536b3f878111148ab7040614e28bf7b8ff8569f585','unassigned',1.78962432944236588e+09);
INSERT INTO "artifacts" VALUES('DOMAIN-33e6d77ce0de46f5eea615ff','PRJ-457c6370f049cdb2538542dc','domain',1,'accepted','{"interfaces":[],"non_responsibilities":["Persistence"],"owned_data":[],"responsibilities":["Integer addition"],"statement":"Arithmetic boundary","title":"Arithmetic boundary"}','379876018784d0763dd15da26200d74ca17703b8b787851ce44db1c22227c925','unassigned',1.789624329448668e+09);
INSERT INTO "artifacts" VALUES('INTERFACE-47f0dd6469669bc6485afa2b','PRJ-457c6370f049cdb2538542dc','interface',1,'accepted','{"authentication":"none","compatibility":"additive","consumers":[],"errors":"none","idempotency":"pure","input":"two integers","output":"one integer","statement":"Arithmetic interface","title":"Arithmetic interface","verification":"test_calc.py"}','f8ed97976120af8983ee6ab4ea4f341e4d570db736f355ef72e5129c7467a1e1','unassigned',1.78962432945449185e+09);
INSERT INTO "artifacts" VALUES('FINDING-62549d401195ecad247f32f3','PRJ-457c6370f049cdb2538542dc','finding',1,'accepted','{"bounded_experiment":"Before implementation, inspect the source obligation, the repository language/runtime, and the fixed test command; no production change is needed to establish feasibility.","hypothesis":"The required inputs are integers and the runtime preserves exact integer addition for the supplied finite and large-value cases.","observed_results":"The source, repository profile, and test plan constrain the change to calc.py and test_calc.py; no dependency, migration, I/O, or service boundary is present.","remaining_unknowns":["The implementation must still be executed and the complete fixed test command must pass."],"source_refs":["SRC-0d2b807ae30652c95ff26469"],"statement":"Exact integer addition is feasible in the bounded CPython repository because add(a, b) can use Python''s integer + operation with no external service or persistence.","title":"Arithmetic feasibility"}','6ba28b2c16e15bf537c398131f52fc73304b3c297bb62c3c55a89f56d4e956d2','unassigned',1.78962432946214246e+09);
INSERT INTO "artifacts" VALUES('DESIGN-b25fd99e5117dbcdd25beefc','PRJ-457c6370f049cdb2538542dc','design',1,'accepted','{"failure_handling":"A failing repository test blocks completion and delivery certification.","rejected_alternatives":["Subtraction or float conversion would violate exact integer semantics."],"responsibilities":["Return the mathematical integer sum","Preserve the existing test entry point"],"rollout":"The bounded local repository has no persistent state; the verified file snapshot is the only release input.","source_refs":["SRC-0d2b807ae30652c95ff26469"],"statement":"Implement add(a, b) as the exact integer sum a + b in calc.py and preserve the repository test contract.","title":"Arithmetic implementation design"}','c5771f24fed86fdc01a71eed1421aef0f934dbccda993b03c935c2a38530c43f','unassigned',1789624329.47006);
INSERT INTO "artifacts" VALUES('TEST-9cbc169c1810302b84da62e5','PRJ-457c6370f049cdb2538542dc','test',1,'accepted','{"cases":["add(2, 3) == 5","The existing test remains enabled and unchanged"],"command":"python -m pytest -q test_calc.py","evidence":"The delivery profile repeats this check as smoke, integration, and scenario verification.","source_refs":["SRC-0d2b807ae30652c95ff26469"],"statement":"Run the fixed repository test and verify add(2, 3) returns 5 without weakening the existing assertion.","title":"Arithmetic verification"}','8ab0d41b2427445f74bc90a8ef9ffa327bee20f05fb3e0f1f2384a4d53d544c9','unassigned',1.78962432947717976e+09);
