INSERT INTO "breakdown_packets" VALUES('BPACK-0bcbcf939ab2f30385f6a24640a419eaabb0cfbeb7008ba2569b3099f5f744eb','PRJ-75d83109852601a17d6a1595','{"end":1244,"format":"daikibo.breakdown-review.v1","instructions":"This is a fragment, not the whole system. Review design and trace separately. Include this exact fragment marker in covered only after inspecting it; return blocked when necessary context is missing. Query breakdown.get/packet for related fragments.","material_digest":"40b393677b0425e969de72b9ce583b42e15e47999ae523219a139301603c75dd","program":"FLOW-3c1451ca6af57e9d9700039f","required_coverage":["PART-534f994d81170f4b7462086ad89a92a16ab26abeeaeefb589e467280a591b0d9"],"serialized_fragment":"{\"current_scope\":{\"policy\":\"9435349ba663f23b292c6d76896a59a13217510e2b55f471ade09a2d03bae02c\",\"requirements\":[{\"acceptance\":[\"AC-CLOSED\"],\"digest\":\"fc5dbf3510de50d550a583a5e7611252c0bfa5f0cf225f8957fd978c8725105d\",\"id\":\"REQUIREMENT-568a71cc469eb381ebc19d8e\",\"revision\":1}],\"tasks\":[{\"definition_digest\":\"72f9c75a0b15a1324e72356afc538635dcb3522c3b6bf735ee40b0f1d8df60be\",\"id\":\"TASK-0ab3961f86c73f9588512960\"}]},\"format\":\"daikibo.breakdown.v1\",\"program\":\"FLOW-3c1451ca6af57e9d9700039f\",\"rationale\":\"Retain all scope\",\"review_question\":\"Check complete coverage, hierarchical responsibility, real task dependency order, cross-domain contracts, and whether the split actually serves user scenarios. Counts alone are not correctness.\",\"title\":\"Closed plan\",\"units\":[{\"dependencies\":[],\"domain\":null,\"id\":\"system\",\"interfaces\":[],\"obligations\":[],\"parent\":null,\"rationale\":\"Aggregate only\",\"tasks\":[],\"title\":\"system\"},{\"dependencies\":[],\"domain\":\"DOMAIN-25a6ad6caa7114eb16f62212\",\"id\":\"arithmetic\",\"interfaces\":[],\"obligations\":[{\"acceptance\":\"AC-CLOSED\",\"requirement\":\"REQUIREMENT-568a71cc469eb381ebc19d8e\"}],\"parent\":\"system\",\"rationale\":\"Own the complete arithmetic responsibility\",\"tasks\":[\"TASK-0ab3961f86c73f9588512960\"],\"title\":\"arithmetic\"}]}","start":0,"total_characters":1244,"unit":"__structure__"}','0bcbcf939ab2f30385f6a24640a419eaabb0cfbeb7008ba2569b3099f5f744eb',1.78962433021296095e+09);
INSERT INTO "breakdown_packets" VALUES('BPACK-a035432b0efff54f43b48368354e3b8be5de6c647557333c414d900f48676f3d','PRJ-75d83109852601a17d6a1595','{"end":7762,"format":"daikibo.breakdown-review.v1","instructions":"This is a fragment, not the whole system. Review design and trace separately. Include this exact fragment marker in covered only after inspecting it; return blocked when necessary context is missing. Query breakdown.get/packet for related fragments.","material_digest":"fb09c9c3d4761e6b397fc1326da957a78fdc75be565dbf54cb02a6784c53fd22","program":"FLOW-3c1451ca6af57e9d9700039f","required_coverage":["PART-a0948b5b8c47b5dbeed5ccb51e405fc4df2f974276858c7901ec4154a0451a18"],"serialized_fragment":"{\"artifacts\":[{\"body\":{\"failure_handling\":\"A failing repository test blocks completion and delivery certification.\",\"rejected_alternatives\":[\"Subtraction or float conversion would violate exact integer semantics.\"],\"responsibilities\":[\"Return the mathematical integer sum\",\"Preserve the existing test entry point\"],\"rollout\":\"The bounded local repository has no persistent state; the verified file snapshot is the only release input.\",\"source_refs\":[\"SRC-1e7476eb6ee408298b2ca29d\"],\"statement\":\"Implement add(a, b) as the exact integer sum a + b in calc.py and preserve the repository test contract.\",\"title\":\"Arithmetic implementation design\"},\"digest\":\"3b332915a69a24acc06bd1c735dd89ba2fcf2e410d889a14e2c1fd174a0bff9c\",\"id\":\"DESIGN-720bf64fb8fa816a48ce4459\",\"kind\":\"design\",\"owner\":\"unassigned\",\"revision\":1,\"status\":\"accepted\"},{\"body\":{\"interfaces\":[],\"non_responsibilities\":[\"Persistence\"],\"owned_data\":[],\"responsibilities\":[\"Integer addition\"],\"statement\":\"Arithmetic boundary\",\"title\":\"Arithmetic boundary\"},\"digest\":\"379876018784d0763dd15da26200d74ca17703b8b787851ce44db1c22227c925\",\"id\":\"DOMAIN-25a6ad6caa7114eb16f62212\",\"kind\":\"domain\",\"owner\":\"unassigned\",\"revision\":1,\"status\":\"accepted\"},{\"body\":{\"bounded_experiment\":\"Before implementation, inspect the source obligation, the repository language/runtime, and the fixed test command; no production change is needed to establish feasibility.\",\"hypothesis\":\"The required inputs are integers and the runtime preserves exact integer addition for the supplied finite and large-value cases.\",\"observed_results\":\"The source, repository profile, and test plan constrain the change to calc.py and test_calc.py; no dependency, migration, I/O, or service boundary is present.\",\"remaining_unknowns\":[\"The implementation must still be executed and the complete fixed test command must pass.\"],\"source_refs\":[\"SRC-1e7476eb6ee408298b2ca29d\"],\"statement\":\"Exact integer addition is feasible in the bounded CPython repository because add(a, b) can use Python''s integer + operation with no external service or persistence.\",\"title\":\"Arithmetic feasibility\"},\"digest\":\"c71e92857868b787f5be2559b8dd9b21077e64162d656f0af5ff26890327c5b0\",\"id\":\"FINDING-a9a6862a8a3671c8780faa81\",\"kind\":\"finding\",\"owner\":\"unassigned\",\"revision\":1,\"status\":\"accepted\"},{\"body\":{\"authentication\":\"none\",\"compatibility\":\"additive\",\"consumers\":[],\"errors\":\"none\",\"idempotency\":\"pure\",\"input\":\"two integers\",\"output\":\"one integer\",\"statement\":\"Arithmetic interface\",\"title\":\"Arithmetic interface\",\"verification\":\"test_calc.py\"},\"digest\":\"f8ed97976120af8983ee6ab4ea4f341e4d570db736f355ef72e5129c7467a1e1\",\"id\":\"INTERFACE-1d9b3c4ecee1628a3e8b4253\",\"kind\":\"interface\",\"owner\":\"unassigned\",\"revision\":1,\"status\":\"accepted\"},{\"body\":{\"acceptance\":[\"AC-CLOSED\"],\"source_refs\":[\"SRC-1e7476eb6ee408298b2ca29d\"],\"statement\":\"The managed function returns the exact integer sum.\",\"title\":\"Closed arithmetic requirement\"},\"digest\":\"fc5dbf3510de50d550a583a5e7611252c0bfa5f0cf225f8957fd978c8725105d\",\"id\":\"REQUIREMENT-568a71cc469eb381ebc19d8e\",\"kind\":\"requirement\",\"owner\":\"unassigned\",\"revision\":1,\"status\":\"accepted\"},{\"body\":{\"concurrent_journey\":[\"Independent calls with distinct integer inputs may run concurrently because the function has no shared state or persistence.\"],\"failure_journey\":[\"If the result is not 5, the test fails and the delivery cannot be certified.\",\"If the source or test cannot be read, stop and report the missing material instead of claiming success.\"],\"nonfunctional\":[\"The function is deterministic and performs no I/O or persistent mutation.\",\"No latency or throughput target is supplied by the bounded source; performance acceptance is therefore not applicable.\"],\"source_refs\":[\"SRC-1e7476eb6ee408298b2ca29d\"],\"statement\":\"A caller supplies two integers to add(a, b), receives their exact sum, and the repository test confirms add(2, 3) == 5.\",\"success_journey\":[\"Invoke add(2, 3).\",\"Observe the integer result 5.\",\"Run the repository test and retain the passing result as the AC-CLOSED evidence.\"],\"title\":\"Normal arithmetic scenario\"},\"digest\":\"132de37e5ad19c3bd09fff6dd2bd8c53a59f553bd0b1265df3e5b6229192f6b6\",\"id\":\"SCENARIO-852d1e71322c3f693c9d6f08\",\"kind\":\"scenario\",\"owner\":\"unassigned\",\"revision\":1,\"status\":\"accepted\"},{\"body\":{\"cases\":[\"add(2, 3) == 5\",\"The existing test remains enabled and unchanged\"],\"command\":\"python -m pytest -q test_calc.py\",\"evidence\":\"The delivery profile repeats this check as smoke, integration, and scenario verification.\",\"source_refs\":[\"SRC-1e7476eb6ee408298b2ca29d\"],\"statement\":\"Run the fixed repository test and verify add(2, 3) returns 5 without weakening the existing assertion.\",\"title\":\"Arithmetic verification\"},\"digest\":\"7ae9382186e2e848f49107eefb22519339d4da96784c8a06568075519d5e63ce\",\"id\":\"TEST-6094f7e1ccb36d65983bfff5\",\"kind\":\"test\",\"owner\":\"unassigned\",\"revision\":1,\"status\":\"accepted\"}],\"format\":\"daikibo.breakdown.v1\",\"policy\