INSERT INTO "revisions" VALUES('SCENARIO-c385b9e57ed45a03c6461495',1,'{"concurrent_journey":["Independent calls with distinct integer inputs may run concurrently because the function has no shared state or persistence."],"failure_journey":["If the result is not 5, the test fails and the delivery cannot be certified.","If the source or test cannot be read, stop and report the missing material instead of claiming success."],"nonfunctional":["The function is deterministic and performs no I/O or persistent mutation.","No latency or throughput target is supplied by the bounded source; performance acceptance is therefore not applicable."],"source_refs":["SRC-0d2b807ae30652c95ff26469"],"statement":"A caller supplies two integers to add(a, b), receives their exact sum, and the repository test confirms add(2, 3) == 5.","success_journey":["Invoke add(2, 3).","Observe the integer result 5.","Run the repository test and retain the passing result as the AC-CLOSED evidence."],"title":"Normal arithmetic scenario"}','c25da034b44fdcc608e55e536b3f878111148ab7040614e28bf7b8ff8569f585','draft','initial proposal','local-user',1.78962432944236588e+09);
