INSERT INTO "revisions" VALUES('SCENARIO-852d1e71322c3f693c9d6f08',1,'{"concurrent_journey":["Independent calls with distinct integer inputs may run concurrently because the function has no shared state or persistence."],"failure_journey":["If the result is not 5, the test fails and the delivery cannot be certified.","If the source or test cannot be read, stop and report the missing material instead of claiming success."],"nonfunctional":["The function is deterministic and performs no I/O or persistent mutation.","No latency or throughput target is supplied by the bounded source; performance acceptance is therefore not applicable."],"source_refs":["SRC-1e7476eb6ee408298b2ca29d"],"statement":"A caller supplies two integers to add(a, b), receives their exact sum, and the repository test confirms add(2, 3) == 5.","success_journey":["Invoke add(2, 3).","Observe the integer result 5.","Run the repository test and retain the passing result as the AC-CLOSED evidence."],"title":"Normal arithmetic scenario"}','132de37e5ad19c3bd09fff6dd2bd8c53a59f553bd0b1265df3e5b6229192f6b6','draft','initial proposal','local-user',1.78962433011522269e+09);
